pub struct Map {
    pub attributes: Vec<(String, String)>,
    pub styles: crate::Style,
    pub events: Vec<(String, VdomEventHandler)>,
    pub children: Vec<VdomNode>,
}
impl Default for Map {
    fn default() -> Self {
        Self::new()
    }
}
impl Map {
    pub fn new() -> Self {
        Self {
            attributes: Vec::new(),
            styles: crate::Style::new(),
            events: Vec::new(),
            children: Vec::new(),
        }
    }
    pub fn attribute(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
        let key = key.into();
        self.attributes
            .push((crate::normalize_attribute_name(&key), value.into()));
        self
    }
    pub fn id(self, value: impl Into<String>) -> Self {
        self.attribute("id", value)
    }
    pub fn class(self, value: impl Into<String>) -> Self {
        self.attribute("class", value)
    }
    pub fn type_(self, value: impl Into<String>) -> Self {
        self.attribute("type", value)
    }
    pub fn style(mut self, style: impl Into<crate::Style>) -> Self {
        self.styles = style.into();
        self
    }
    pub fn popover(self) -> Self {
        self.attribute("popover", "auto")
    }
    pub fn children(mut self, children: impl Into<Vec<VdomNode>>) -> Self {
        self.children = children.into();
        self
    }
    pub fn into_node(self) -> VdomNode {
        VdomNode::Element(VdomElement {
            element_name: "map".to_string(),
            attributes: self.attributes,
            styles: self.styles,
            events: self.events,
            children: self.children,
        })
    }
}
